//www.dndbeyond.com/sources/dnd/mm-2024/monsters-p#Pseudodragon","pages":[249]}]}]},{"number":63,"a":3,"b":6,"pair":"Construct + Elemental","type":"E","title":"Stone Guardian","description":"Summon a Gargoyle for 10 minutes, once per Long Rest. It disappears immediately if you become Incapacitated.","notes":"","review":false,"referenceNote":"","revision":5,"rulesReferences":[{"title":"Creature stat blocks \u00b7 Monster Manual (2024)","links":[{"label":"Gargoyle","url":"https://www.dndbeyond.com/sources/dnd/mm-2024/monsters-g#Gargoyle","pages":[128]}]},{"title":"Conditions and Concentration \u00b7 Player\u2019s Handbook (2024)","links":[{"label":"Incapacitated","pages":[369],"book":"phb"}]}]},{"number":64,"a":3,"b":7,"pair":"Construct + Euryale","type":"N","title":"Stonebound Flesh","description":"Your skin hardens into stone. Suffer a \u22121 penalty to Dexterity saving throws and reduce walking speed by 10 feet until Remove Curse.","notes":"","review":false,"referenceNote":"","revision":5,"rulesReferences":[{"title":"Spells \u00b7 Player\u2019s Handbook (2024)","links":[{"label":"Remove Curse","url":"https://www.dndbeyond.com/spells","pages":[312],"book":"phb"}]}]},{"number":65,"a":3,"b":8,"pair":"Construct + Fey","type":"P","title":"Enchanted Automaton","description":"Permanently gain a Sprite familiar.","notes":"","review":false,"referenceNote":"","revision":5,"rulesReferences":[{"title":"Creature stat blocks \u00b7 Monster Manual (2024)","links":[{"label":"Sprite","url":"https://www.dndbeyond.com/sources/dnd/mm-2024/monsters-s#Sprite","pages":[298]}]}]},{"number":66,"a":3,"b":9,"pair":"Construct + Fiend","type":"P","title":"Infernal Sentinel","description":"Summon an Imp for 1 minute, once per Long Rest.","notes":"","review":false,"referenceNote":"","revision":5,"rulesReferences":[{"title":"Creature stat blocks \u00b7 Monster Manual (2024)","links":[{"label":"Imp","url":"https://www.dndbeyond.com/sources/dnd/mm-2024/monsters-i#Imp","pages":[177]}]}]},{"number":67,"a":3,"b":10,"pair":"Construct + Giant","type":"P","title":"Living Golem","description":"Once per Long Rest, gain a golem-like appearance for 1 minute, 15 Temporary HP, and advantage on Strength checks.","notes":"","review":false,"referenceNote":"","revision":5},{"number":68,"a":3,"b":11,"pair":"Construct + Humanoid","type":"P","title":"Artificial Identity","description":"Once per Long Rest, cast Disguise Self to resemble a Humanoid or Construct within the spell's normal limitations.","notes":"","review":false,"referenceNote":"","revision":5,"rulesReferences":[{"title":"Spells \u00b7 Player\u2019s Handbook (2024)","links":[{"label":"Disguise Self","url":"https://www.dndbeyond.com/spells","pages":[262,263],"book":"phb"}]}]},{"number":69,"a":3,"b":12,"pair":"Construct + Jester","type":"N","title":"Clockwork Parasite","description":"Permanently reduce your maximum number of attuned magic items by one. Immediately unattune an item if necessary. Permanent \u2014 Cannot Be Cured.","notes":"","review":false,"referenceNote":"","revision":5},{"number":70,"a":3,"b":13,"pair":"Construct + Moon","type":"E","title":"Living Armor","description":"Once per Long Rest, gain +2 AC, resistance to bludgeoning damage from nonmagical attacks, and immunity to being Frightened for 1 minute.","notes":"","review":false,"referenceNote":"","revision":5,"rulesReferences":[{"title":"Conditions and Concentration \u00b7 Player\u2019s Handbook (2024)","links":[{"label":"Frightened","pages":[367],"book":"phb"}]}]},{"number":71,"a":3,"b":14,"pair":"Construct + Monstrosity","type":"P","title":"Mechanical Basilisk","description":"Summon a Basilisk for 1 minute, once per Long Rest. Its mechanical appearance is cosmetic.","notes":"","review":false,"referenceNote":"","revision":5,"rulesReferences":[{"title":"Creature stat blocks \u00b7 Monster Manual (2024)","links":[{"label":"Basilisk","url":"https://www.dndbeyond.com/sources/dnd/mm-2024/monsters-b#Basilisk","pages":[32]}]}]},{"number":72,"a":3,"b":15,